    #[test]
    fn mapi_empty() {
        assert_eq([].mapi(|i, x| i * x + 1), []);
    }

    #[test]
    fn for_each_empty() {
        let empty_array: [Field; 0] = [];
        empty_array.for_each(|_x| assert(false));
    }

    #[test]
    fn for_eachi_empty() {
        let empty_array: [Field; 0] = [];
        empty_array.for_eachi(|_i, _x| assert(false));
    }

    #[test]
    fn map_example() {
        let a = [1, 2, 3];
        let b = a.map(|a| a * 2);
