    #[test]
    fn for_each_example() {
        let a = [1, 2, 3];
        let mut b = [0, 0, 0];
        let b_ref = &mut b;
        let mut i = 0;
        let i_ref = &mut i;
        a.for_each(|x| {
            b_ref[*i_ref] = x * 2;
            *i_ref += 1;
        });
        assert_eq(b, [2, 4, 6]);
        assert_eq(i, 3);
    }

    #[test]
    fn for_eachi_example() {
        let a = [1, 2, 3];
        let mut b = [0, 0, 0];
